verifier_source:
# Standalone, stdlib-free: no imports, no I/O, no print, no filesystem, no network.
# Deterministic exact integer arithmetic. Fail-closed: any defect raises, so the
# only normal exit is the final return True. The witness is embedded as a literal;
# an orchestrator may substitute its own witness dict by assigning to W before
# calling verify() in the same module scope.

W = {
  'range': {'n_min': 2, 'n_max': 40},
  'bound': {'G_min': 1, 'G_max': 6},
  'argmax_G6': [23, 31],
  'G_value_multiset_over_n_2_to_40': {'1': 12, '2': 11, '3': 6, '4': 6, '5': 2, '6': 2},
  'prime_gap_multiset_consecutive_primes_le_41': {'1': 1, '2': 6, '4': 4, '6': 2},
}

def _is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def _next_prime_dist(n):
    g = 1
    while not _is_prime(n + g):
        g += 1
    return g

def verify():
    lo = W['range']['n_min']
    hi = W['range']['n_max']
    if not (isinstance(lo, int) and isinstance(hi, int) and 2 <= lo <= hi):
        raise ValueError('bad range')
    G = {}
    for n in range(lo, hi + 1):
        G[n] = _next_prime_dist(n)
    # 1. every gap within the certified bounds
    for n in sorted(G):
        g = G[n]
        if not (W['bound']['G_min'] <= g <= W['bound']['G_max']):
            raise ValueError('gap bound violated at n=%d g=%d' % (n, g))
    # 2. G = G_max exactly at the claimed argmax set
    got = sorted(n for n in G if G[n] == W['bound']['G_max'])
    if got != sorted(W['argmax_G6']):
        raise ValueError('argmax mismatch: %r' % (got,))
    # 3. exact multiset of G-values over the sweep
    ms = {}
    for n in G:
        k = str(G[n])
        ms[k] = ms.get(k, 0) + 1
    if ms != W['G_value_multiset_over_n_2_to_40']:
        raise ValueError('G multiset mismatch: %r' % (ms,))
    # 4. exact multiset of gaps between consecutive primes up to hi+1 = 41
    pr = [p for p in range(2, hi + 2) if _is_prime(p)]
    np_le_40 = 0
    for p in pr:
        if p <= 40:
            np_le_40 += 1
    if np_le_40 != 12:
        raise ValueError('prime count <= 40 mismatch: %d' % np_le_40)
    pm = {}
    for i in range(len(pr) - 1):
        k = str(pr[i + 1] - pr[i])
        pm[k] = pm.get(k, 0) + 1
    if pm != W['prime_gap_multiset_consecutive_primes_le_41']:
        raise ValueError('prime-gap multiset mismatch: %r' % (pm,))
    return True
